mapper.select:
SELECT p.* FROM product p
JOIN (
SELECT product_id FROM product_attribute


		(
		attribute_name = #{key} AND attribute_value IN

			#{val}

		)


GROUP BY product_id
HAVING COUNT(DISTINCT attribute_name) = #{conditionCount}
) f ON p.id = f.product_id
WHERE p.category = '사료' AND p.animal_type = '고양이'

